            if(pos == 0){
                doOp(1, n-2); // prefix=[p0] goes to end, pos becomes n-1
            } else {
                // x=pos, y=n-1-pos. Element at pos is middle[0], new pos = (n-1-pos)
                // Repeat: if new pos != n-1, do again
                int x=pos, y=n-1-pos;
                doOp(x,y);
                pos = n-1-pos;
                if(pos != n-1 && pos > 0){
                    doOp(pos, n-1-pos);
                    pos = n-1-pos;
                }
                if(pos!=n-1){ doOp(1,n-2); pos=n-1; }
            }
        }
        // Step 2: element at n-1, move to k
        if(k < n-1){
            // y=n-1-k, x=1: new=[p[k+1..n-1], p[1..k], p[0]]. Element at n-1 goes to pos n-2-k. Nope.
            // y=1: element goes to pos 0. x=n-2: new=[p[n-1], p[n-2..n-2]???] Hmm
            int y = n-1-k, x = 1;
            if(x>0&&y>0&&x+y<n) doOp(x,y);
            // Now element is at pos y-1 = n-2-k... redo
            // Actually just use: x=k+1,y=1 => el at n-1 in suffix, goes to pos 0. Then x=k,y=1 to rotate
            // This moves prefix to end though...
            // Let me just brute force correct placement
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
